namespace Qms.Domain.MasterBatchRecords;
public enum MasterBatchRecordStatus{Draft,InReview,Reviewed,Approved,Effective,Superseded,Archived}
public sealed class MasterBatchRecord
{
 private readonly List<MasterBatchStep>_steps=[];private MasterBatchRecord(){}public Guid Id{get;private set;}public Guid QualityRecordId{get;private set;}public Guid?PreviousVersionId{get;private set;}public string ProductCode{get;private set;}="";public string ProductName{get;private set;}="";public string DosageFormCode{get;private set;}="";public string DosageFormName{get;private set;}="";public string Strength{get;private set;}="";public decimal BatchSize{get;private set;}public string BatchUnitCode{get;private set;}="";public string BatchUnitName{get;private set;}="";public string SiteCode{get;private set;}="";public string SiteName{get;private set;}="";public string LineCode{get;private set;}="";public string LineName{get;private set;}="";public string DocumentVersion{get;private set;}="";public string ChangeReason{get;private set;}="";public Guid AuthorUserId{get;private set;}public string Author{get;private set;}="";public Guid ReviewerUserId{get;private set;}public string Reviewer{get;private set;}="";public Guid ApproverUserId{get;private set;}public string Approver{get;private set;}="";public DateTimeOffset?EffectiveAtUtc{get;private set;}public MasterBatchRecordStatus Status{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public DateTimeOffset UpdatedAtUtc{get;private set;}public long Version{get;private set;}public IReadOnlyCollection<MasterBatchStep>Steps=>_steps;
 public static MasterBatchRecord Create(Guid qr,Guid?previous,string productCode,string productName,string formCode,string formName,string strength,decimal batchSize,string unitCode,string unitName,string siteCode,string siteName,string lineCode,string lineName,string documentVersion,string changeReason,Guid authorId,string author,Guid reviewerId,string reviewer,Guid approverId,string approver,DateTimeOffset now){if(qr==Guid.Empty||authorId==Guid.Empty||reviewerId==Guid.Empty||approverId==Guid.Empty||batchSize<=0||authorId==reviewerId||authorId==approverId||reviewerId==approverId)throw new ArgumentException("MBR kimlikleri, görev ayrılığı veya batch miktarı geçersizdir.");foreach(var v in new[]{productCode,productName,formCode,formName,strength,unitCode,unitName,siteCode,siteName,lineCode,lineName,documentVersion,changeReason,author,reviewer,approver})Text(v);return new(){Id=Guid.CreateVersion7(),QualityRecordId=qr,PreviousVersionId=previous,ProductCode=productCode.Trim(),ProductName=productName.Trim(),DosageFormCode=formCode.Trim(),DosageFormName=formName.Trim(),Strength=strength.Trim(),BatchSize=batchSize,BatchUnitCode=unitCode.Trim(),BatchUnitName=unitName.Trim(),SiteCode=siteCode.Trim(),SiteName=siteName.Trim(),LineCode=lineCode.Trim(),LineName=lineName.Trim(),DocumentVersion=documentVersion.Trim(),ChangeReason=changeReason.Trim(),AuthorUserId=authorId,Author=author.Trim(),ReviewerUserId=reviewerId,Reviewer=reviewer.Trim(),ApproverUserId=approverId,Approver=approver.Trim(),Status=MasterBatchRecordStatus.Draft,CreatedAtUtc=now,UpdatedAtUtc=now,Version=1};}
 public void AddStep(long v,MasterBatchStep step,DateTimeOffset now){Ensure(v,MasterBatchRecordStatus.Draft);if(_steps.Any(x=>x.Order==step.Order))throw new InvalidOperationException("Aynı işlem sıra numarası kullanılamaz.");_steps.Add(step);Touch(now);}public void SubmitReview(long v,DateTimeOffset now){Ensure(v,MasterBatchRecordStatus.Draft);if(_steps.Count==0)throw new InvalidOperationException("MBR en az bir kontrollü işlem adımı içermelidir.");if(_steps.Any(x=>x.IsCritical&&!x.HasDefinedLimit))throw new InvalidOperationException("Kritik adımlar için parametre, alt/üst limit ve birim zorunludur.");Move(MasterBatchRecordStatus.InReview,now);}public void CompleteReview(long v,DateTimeOffset now){Ensure(v,MasterBatchRecordStatus.InReview);Move(MasterBatchRecordStatus.Reviewed,now);}public void Approve(long v,DateTimeOffset now){Ensure(v,MasterBatchRecordStatus.Reviewed);Move(MasterBatchRecordStatus.Approved,now);}public void MakeEffective(long v,DateTimeOffset effective,DateTimeOffset now){Ensure(v,MasterBatchRecordStatus.Approved);if(effective<now.AddMinutes(-1))throw new ArgumentException("Yürürlük tarihi geçmişte olamaz.");EffectiveAtUtc=effective;Move(MasterBatchRecordStatus.Effective,now);}public void Supersede(DateTimeOffset now){if(Status!=MasterBatchRecordStatus.Effective)throw new InvalidOperationException("Yalnız yürürlükteki MBR supersede edilebilir.");Move(MasterBatchRecordStatus.Superseded,now);}private void Ensure(long v,MasterBatchRecordStatus s){if(Version!=v)throw new InvalidOperationException("MBR değişti; ekranı yenileyin.");if(Status!=s)throw new InvalidOperationException($"Geçersiz MBR aşaması: {Status}.");}private void Move(MasterBatchRecordStatus s,DateTimeOffset n){Status=s;Touch(n);}private void Touch(DateTimeOffset n){UpdatedAtUtc=n;Version++;}private static void Text(string v){if(string.IsNullOrWhiteSpace(v)||v.Trim().Length>6000)throw new ArgumentException("MBR zorunlu metni geçersizdir.");}
}
public sealed class MasterBatchStep{private MasterBatchStep(){}public Guid Id{get;private set;}public Guid MasterBatchRecordId{get;private set;}public int Order{get;private set;}public string PhaseCode{get;private set;}="";public string PhaseName{get;private set;}="";public string Instruction{get;private set;}="";public string?MaterialOrEquipmentReference{get;private set;}public bool IsCritical{get;private set;}public string?Parameter{get;private set;}public decimal?LowerLimit{get;private set;}public decimal?UpperLimit{get;private set;}public string?UnitCode{get;private set;}public string?UnitName{get;private set;}public bool HasDefinedLimit=>!IsCritical||(!string.IsNullOrWhiteSpace(Parameter)&&LowerLimit.HasValue&&UpperLimit.HasValue&&LowerLimit<=UpperLimit&&!string.IsNullOrWhiteSpace(UnitCode));public static MasterBatchStep Create(Guid mbr,int order,string phaseCode,string phaseName,string instruction,string?reference,bool critical,string?parameter,decimal?lower,decimal?upper,string?unitCode,string?unitName){if(mbr==Guid.Empty||order<1||string.IsNullOrWhiteSpace(phaseCode)||string.IsNullOrWhiteSpace(phaseName)||string.IsNullOrWhiteSpace(instruction))throw new ArgumentException("MBR işlem adımı geçersizdir.");var x=new MasterBatchStep{Id=Guid.CreateVersion7(),MasterBatchRecordId=mbr,Order=order,PhaseCode=phaseCode.Trim(),PhaseName=phaseName.Trim(),Instruction=instruction.Trim(),MaterialOrEquipmentReference=Clean(reference),IsCritical=critical,Parameter=Clean(parameter),LowerLimit=lower,UpperLimit=upper,UnitCode=Clean(unitCode),UnitName=Clean(unitName)};if(!x.HasDefinedLimit)throw new ArgumentException("Kritik MBR adımının kontrollü limitleri eksiktir.");return x;}private static string?Clean(string?v)=>string.IsNullOrWhiteSpace(v)?null:v.Trim();}
